def factory(cfg, secrets_ref):
    async def listTools(_ctx=None):
        return {"ok": True, "tools": [{"name": "bundled", "description": "from bundle"}]}
    async def runTool(ctx):
        return {
            "ok": True,
            "bundled": True,
            "tool": (ctx or {}).get("tool"),
            "secrets_ref": secrets_ref,
            "cfg_flag": (cfg or {}).get("flag"),
        }
    return {"listTools": listTools, "runTool": runTool}
